{
  "agenda_setting_politica_deporte": {
    "definicion": "La agenda‑setting orientada a política y deporte consiste en privilegiar la aparición de temas políticos y deportivos en la cobertura mediática, influyendo en la percepción pública sobre qué asuntos son relevantes. Los medios eligen con frecuencia titulares, horarios de emisión y espacio editorial para estos tópicos, desplazando otras áreas de interés.",
    "ejemplo": "En la cobertura de la campaña electoral de 2024 en España, los principales diarios dedicaron el 40% de su portada a debates políticos y a la Copa del Mundo de fútbol, mientras que temáticas como educación o cambio climático recibieron menos del 5% de la atención.",
    "como_detectarla": "1. Analizar la proporción de espacio editorial (páginas, minutos) asignada a política y deporte frente a otros temas. 2. Comparar la frecuencia de aparición de estos asuntos con la agenda pública (encuestas de prioridades ciudadanas). 3. Identificar patrones de repetición de titulares y colocación privilegiada (portada, primicia)."
  },
  "enfoque_selectivo_controversias_politicas": {
    "definicion": "El enfoque selectivo en controversias políticas se refiere a la tendencia de los medios a cubrir sólo los conflictos que generan mayor polarización o escándalo, omitiendo o minimizando debates menos sensacionalistas pero de gran relevancia social.",
    "ejemplo": "Durante la discusión del proyecto de ley de vivienda en México (2023‑2024), los principales canales de televisión resaltaron los enfrentamientos entre partidos, mientras que los datos sobre la crisis habitacional y propuestas de solución fueron escasamente tratados.",
    "como_detectarla": "1. Revisar la variedad de fuentes y actores citados; un sesgo hacia opositores y confrontaciones indica selección. 2. Medir la cobertura de hechos sustantivos (estadísticas, propuestas) frente a discursos polémicos. 3. Contrastar la agenda mediática con informes de organizaciones civiles que documenten la totalidad del debate."
  },
  "framing_conflicto_politico_vs_tecnologico": {
    "definicion": "Este framing reinterpreta un hecho tecnológico como conflicto político, enfatizando luchas de poder, intereses partidistas o ideológicos y desdibujando la dimensión técnica o científica del asunto.",
    "ejemplo": "Al reportar la polémica sobre la implantación de redes 5G en Alemania (2024), varios periódicos describieron la discusión como una batalla entre el gobierno y partidos de la oposición, omitiendo la exposición de los estudios de seguridad y los beneficios económicos del proyecto.",
    "como_detectarla": "1. Identificar la presencia de vocabulario político (\"batalla\", \"gobernar\", \"oposición\") en lugar de términos técnicos. 2. Verificar la ausencia o escasa referencia a datos científicos o expertos del sector. 3. Comparar con comunicados oficiales de entidades tecnológicas que describen el tema con enfoque técnico."
  },
  "framing_noticias_locales_culturales": {
    "definicion": "El framing de noticias locales y culturales consiste en presentar eventos o fenómenos de una comunidad bajo una óptica que resalta valores, identidades o problemáticas específicas, a menudo reforzando estereotipos o agendas regionales.",
    "ejemplo": "En la cobertura del festival de música tradicional de Oaxaca (2024), los medios nacionales destacaron el aspecto \"exótico\" y la supuesta vulnerabilidad cultural, mientras que la prensa local resaltó la innovación y el impacto económico del evento.",
    "como_detectarla": "1. Analizar el tono y los adjetivos usados (exótico, vulnerable, tradicional). 2. Comparar la información ofrecida por medios locales versus nacionales para detectar diferencias de enfoque. 3. Evaluar la inclusión de voces de la comunidad frente a fuentes externas que interpretan el suceso."
  },
  "omision_tema_relevante": {
    "definicion": "La omisión de tema relevante es la práctica deliberada o inadvertida de excluir de la agenda mediática asuntos de alta importancia social, política o económica, creando una percepción distorsionada de la realidad pública.",
    "ejemplo": "Durante la crisis energética en Chile (2023‑2024), los principales noticieros nocturnos apenas mencionaron la escasez de gas en regiones del sur, concentrándose en la inflación y la política fiscal, a pesar de que encuestas mostraban que el 68% de la población consideraba la energía su mayor preocupación.",
    "como_detectarla": "1. Contrastar la cobertura mediática con indicadores de relevancia (encuestas, datos oficiales) para detectar lagunas. 2. Realizar un análisis de contenido cuantitativo que cuente menciones de temas críticos en un periodo dado. 3. Revisar la agenda de prensa de organizaciones y expertos que trabajen en el tema omitido para evidenciar la falta de difusión."
  }
}

